import data from "../data/outlets.generated.json";

/**
 * The source list, generated by scripts/discover-feeds.mjs (data/outlets.generated.json).
 *
 * Lean comes from published data, not Tare's judgment: each outlet's audience-lean score ("zeta") from
 * Eady, Bonneau, Tucker & Nagler (2025), "News Sharing and Partisanship on Social Media", Political Analysis,
 * CC0 (data/eady2025). The score measures who shares an outlet's links, scaled so 0 is neutral and 1.24 is
 * the gap between the median Democratic and median Republican member of the 116th Congress. Outlets not in
 * that data (international ones, and specialist tech, science and motorsport outlets) are "unrated": they count
 * as coverage but never toward left or right.
 */
export type Lean = "left" | "lean-left" | "center" | "lean-right" | "right" | "unrated";
export type Side = "left" | "center" | "right";

export type Outlet = {
  id: string;
  name: string;
  domain: string;
  lean: Lean;
  /** Eady et al. 2025 score and its 90% interval; null when unrated. */
  zeta: number | null;
  zetaLow: number | null;
  zetaHigh: number | null;
  feeds: string[];
};

/** Bucket edges on the zeta scale: half and one full Democrat-to-Republican congressional gap either side of 0. */
export const ZETA_EDGES = { left: -1.24, leanLeft: -0.62, leanRight: 0.62, right: 1.24 } as const;

export function leanOf(zeta: number | null | undefined): Lean {
  if (zeta == null || !Number.isFinite(zeta)) return "unrated";
  if (zeta < ZETA_EDGES.left) return "left";
  if (zeta < ZETA_EDGES.leanLeft) return "lean-left";
  if (zeta <= ZETA_EDGES.leanRight) return "center";
  if (zeta <= ZETA_EDGES.right) return "lean-right";
  return "right";
}

type Raw = { id: string; name: string; domain: string; zeta?: number; zetaLow?: number; zetaHigh?: number; feeds: string[] };

export const OUTLETS: readonly Outlet[] = (data.outlets as Raw[]).map((o) => ({
  id: o.id,
  name: o.name,
  domain: o.domain,
  lean: leanOf(o.zeta),
  zeta: o.zeta ?? null,
  zetaLow: o.zetaLow ?? null,
  zetaHigh: o.zetaHigh ?? null,
  feeds: o.feeds,
}));

const BY_ID = new Map(OUTLETS.map((o) => [o.id, o]));

export function outletById(id: string): Outlet | undefined {
  return BY_ID.get(id);
}

/** The side of the scale an outlet counts toward; unrated outlets count toward none. */
export function sideOf(lean: Lean): Side | null {
  if (lean === "left" || lean === "lean-left") return "left";
  if (lean === "right" || lean === "lean-right") return "right";
  if (lean === "center") return "center";
  return null;
}

export const LEAN_LABEL: Record<Lean, string> = {
  left: "Left",
  "lean-left": "Leans left",
  center: "Center",
  "lean-right": "Leans right",
  right: "Right",
  unrated: "Not rated",
};

/** How many rated outlets sit on each side, used to turn counts into shares. */
export const SIDE_SIZE: Record<Side, number> = OUTLETS.reduce(
  (acc, o) => {
    const side = sideOf(o.lean);
    return side ? { ...acc, [side]: acc[side] + 1 } : acc;
  },
  { left: 0, center: 0, right: 0 } as Record<Side, number>,
);
